def pytest_configure(config):
    config.addinivalue_line('markers', 'authentic_data: requires original authenticated historical JPL reference layout')
    config.addinivalue_line('markers', 'data_independent: no observational data required')

def pytest_collection_modifyitems(config, items):
    for item in items:
        if item.nodeid in AUTHENTIC_TESTS:
            item.add_marker(pytest.mark.authentic_data)
            # Only an entirely absent historical baseline earns SKIP. An incomplete,
            # corrupt or incompatible supplied baseline must fail original assertions.
            if not (ROOT/'data/jpl-20261103').exists() and not any((ROOT/'data').glob('*/raw')):
                item.add_marker(pytest.mark.skip(reason='Tier B BLOCKED: original authentic JPL snapshot/results absent; see TESTING.md'))
        else:
            item.add_marker(pytest.mark.data_independent)
